                recall = j;
            if (region.GetName() == CCharString("HeroGuildComplexInside"))
                guild = j;
        }
        CRegion temp;
        long next = 0;
        if (recall != -1) {
            temp = regions[recall];
            regions[recall] = regions[0];
            regions[0] = temp;
            next = 1;
        }
        if (guild != -1 && !(recall == 0 && guild == 1) && !(recall == 1 && guild == 0)) {
            temp = regions[guild];
            regions[guild] = regions[next];
            regions[next] = temp;
        }
        recall = -1;
