                if (GetRegionTeleporter(PeekWorld().PeekWorldMap().GetRegion(region_number))
                    && world_map.GetLoadedRegion() != region_number
                    && PeekWorld().PeekWorldMap().GetRegion(region_number).IsOnWorldMap())
