                        marker_name = quest_card->GetTeleporterRegionName();
                        bool already_listed = false;
                        for (unsigned long j = 0; j < regions.size(); ++j) {
                            if (regions[j].GetRegionDefName() == region.GetRegionDefName()) {
                                already_listed = true;
                                break;
                            }
