Str CAction::Show() const
{
    Str s = Num(ActionType) + (SelfParam ? " self" : "");
    for (size_t i = 0; i < Params.size(); ++i) s += " " + Params[i]->Show();
    for (std::list<CActionParam*>::const_iterator i = UIActionParams.begin(); i != UIActionParams.end(); ++i) s += " " + (*i)->Show();
    return s;
}
