        Check(a.UnassignedIcons[H(9)] == en9->Children[2], "A unassigned icon");
        Check(Child(en3, "PC_SUBTITLE")->Text == "Spell3 - <TEXT_GUI_MENU_LEVEL> 3", "A display name");
