                    unsigned char alpha = ScaleAlpha(0xff);
                    const CFontBank& font = Component->PeekCutSceneMainFont();
                    PlayerGui->Draw2DText(text, name, font, CRGBColour(0xff, 0xff, 0xff, alpha), 0.6f,
                                          (EEngine2DLayer)0x49, true);
                }
            }
        }
