    g_n = 0; Draw(def, v);
    CHECK(Count(BUTTON) == 3 && v.Scale > 0.44f && v.Scale < 0.46f && v.SpecialToNormal);
    v.Paused = true; v.Scale = 0.2f; Draw(def, v);
    CHECK(v.Scale == 0.2f);

    if (g_fail == 0) std::printf("00651b04_TEST PASS\n");
    return g_fail;
}

