    const C3DMesh2* mesh = render_info->Mesh;
    const C3DMeshMaterial* material = mesh->GetMaterial(cloth_primitive.GetMaterialIndex());
    const CGraphicDataBank* graphic_bank = primitive.MeshInfo->PeekTextureBank();
