                        Game->NewScriptFrame();
                        if (IsActiveThreadTerminating()) return;
                    }
                    if (IsActiveThreadTerminating()) return;
                }
                HeroWarnings = 0;
                MasterScriptData->GuildWarningOccuring = false;
