                            Game->ModifyThingHealth(Whisper, 1000.0f, false);
                            Game->EntitySetInFaction(Whisper, "FACTION_HERO");
                        }
                        ParentClass.StartedMeleeTesting = false;
                        PMasterData->HeroTakingGuildTest = false;
                    }
                }
                }
            }
        }
    }
