                        return;
                    }
                    parser.SkipWhitespace();
                    if (!(parser.ReadAsSymbol() == ")")) return;
                }
            }
        }
    }
    else
        context.PersistError(parser, "Unknown command for TOpinionTransientOffsetList");
}

