    Script b = Make(100, 5, 2, 0, 50, false); b.SpringAmbush();
    ok = ok && b.DoAmbush && b.Guards == 6 && b.TricksterKilledAfterAmbush && !b.TricksterKilledBeforeAmbush;
    // trickster dead before the hero arrives
