#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

static std::vector<std::string> g_log;
static void L(const char* f, ...) { char b[256]; va_list a; va_start(a, f); vsprintf(b, f, a); va_end(a); g_log.push_back(b); }

