    static const char* ps[] = { "PSCONST_ZERO", "PSCONST_ONE", "PSCONST_HALF", "PSCONST_1_0_0_0", "PSCONST_0_1_0_0", "PSCONST_0_0_1_0",
                                "PSCONST_0_0_0_1", "PSCONST_SHADOW_FADE_COLOUR", "PSCONST_MAX_FOG_ALPHA", "PSCONST_TFACTOR" };
