        bool full = w == 1.0f;
        for (size_t j = 0; j < chain.size(); ++j) {
            if (a.relative) k[j].angle += full ? a.add : a.add * w;
            else if (a.partial && a.mask[chain[j]]) k[j].angle = full ? a.add : k[j].angle + (a.add - k[j].angle) * w;
