                    items.push_back(std::pair<long,CCharString>(index, ContainerItems[i].second));
            } else if (ContainerItems[i].first == resurrection_index) {
                long index = GetDynamicResurrectionDefIndex();
                if (index > 0)
                    items.push_back(std::pair<long,CCharString>(index, ContainerItems[i].second));
